// Define a typed client
public class GitHubClient
{
    private readonly HttpClient _http;

    public GitHubClient(HttpClient http)
    {
        _http = http;
        _http.BaseAddress = new Uri("https://api.github.com/");
        _http.DefaultRequestHeaders.Add("User-Agent", "Quotient-App");
    }

    public async Task<string> GetUserAsync(string username, CancellationToken ct)
    {
        var response = await _http.GetAsync($"users/{username}", ct);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(ct);
    }
}

// Registration
builder.Services.AddHttpClient<GitHubClient>(client =>
{
    client.Timeout = TimeSpan.FromSeconds(10);
});;

// Usage in a controller or service
public class ProfilesController(GitHubClient github)
{
    public async Task<IActionResult> View(string username)
    {
        var json = await github.GetUserAsync(username, HttpContext.RequestAborted);
        return Content(json, "application/json");
    }
}

builder.Services.AddHttpClient("PaymentGateway", client =>
{
    client.BaseAddress = new Uri("https://payments.example.com/");
    client.Timeout = TimeSpan.FromSeconds(15);
})
.ConfigurePrimaryHttpMessageHandler(() =>
{
    return new HttpClientHandler
    {
        MaxConnectionsPerServer = 10,
        AutomaticDecompression = DecompressionMethods.GZip | DecompressionMethods.Deflate
    };
})
.SetHandlerLifetime(TimeSpan.FromMinutes(5));

builder.Services.AddHttpClient<InventoryClient>(client =>
{
    client.BaseAddress = new Uri("https://inventory.example.com/");
})
.AddTransientHttpErrorPolicy(policy =>
    policy.WaitAndRetryAsync(3, retry => TimeSpan.FromSeconds(Math.Pow(2, retry))))
.AddCircuitBreakerPolicy(policy =>
{
    policy.KeepAlive = TimeSpan.FromSeconds(30);
});
